void f(int i) { /* handles integer */ }
void f(bool b) { /* handles boolean */ }
void f(void* p) { /* handles pointer */ }

// Overload resolution behavior
f(0);         // Calls f(int), not f(void*)
f(NULL);      // Typically calls f(int), but can be ambiguous and fail to compile
f(nullptr);   // Calls f(void*)
